82	// the item is created and the executor, which holds the credentials, decides at
83	// pick. It is REQUIRED wherever a task is asked — a fixture with no seam and a
84	// task to ask is a fixture that has not said what the task answers.
85	export async function planSchedulerRun({
86	  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
87	  stateOf = () => null, evaluate = null,
88	}) {
89	  const nowMs = ms(now);
90	  const ops = [];
91	  const asked = [];
92	  // REPO SHAPE IS NOT A PRECONDITION (docs/PRINCIPLES.md). "This repo ships the store pipeline", "this repo is a canon
93	  // home with a fleet token" are facts adoption settled, not questions worth
94	  // re-asking every tick — so a repo that carries a pack but not one task's
95	  // subject names that task in `taskScheduler.disabledTasks` and it is never
