110	  // dependency, not a schedule's.
111	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
112	  for (const item of items) {
113	    if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED) || !tasks.length) continue;
114	    const parsed = parseWorkItemTitle(item.title);
115	    if (!parsed || parsed.qualifier !== null) continue;
116	    const key = `${parsed.pack}/${parsed.task}`;
117	    if (parseWorkItemBody(item.body).blockedBy.length) continue;
118	    if (byId.has(key) && !disabled.has(key)) continue;
119	    closedByThisRun.add(item.number);
120	    ops.push({
121	      kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
122	      reason: disabled.has(key)
123	        ? `Closing: \`${key}\` is named in this repository's \`taskScheduler.disabledTasks\`, so it is not `
124	          + 'asked here. Remove it from that list to bring the task back.'
125	        : `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `
126	          + 'that is not at HEAD and can never run. If the task came back under a new id, its own item is the live one.',
127	    });
128	  }
