attachment.snippet:
1	// The dashboard's derivation layer — repo facts in, view rows out. Pure: it reads
2	// no clock, opens no socket, and touches no DOM, so the whole of what the page
3	// claims is testable in Node and shared verbatim with the browser.
4	//
5	// It states NONE of the queue's vocabulary itself. The label set, the title
6	// grammar, the leash constants and the anchor arithmetic are imported from the
7	// engine modules that define them, which is what makes a dashboard that cannot
8	// drift from the mechanism it renders: there is no second copy to drift.
9	//
10	// Those engine modules are pure ESM with no `node:` imports, which is the property
11	// this file depends on and `browser-graph.test.mjs` pins across the page's whole
12	// import graph. Living inside `packs/claudinite-tasks/` makes the queue modules siblings,
13	// so the dashboard sits beside the mechanism it renders rather than reaching across
14	// the tree at it.
15	
16	import { parseTaskDeclaration, applyTaskDefaults } from '../../../claudinite-tasks/shared-code/task-declaration.mjs';
17	import {
18	  mostRecentAnchor, nextAnchor, periodMs, taskPeriodMs, cadenceOf, cadenceTermFor, holdsOnFailure, holdsOnAnyPark, statesConditions,
19	  DUE_TERM, ELAPSED_TERM,
20	} from '../../../claudinite-tasks/shared-code/anchors.mjs';
21	import {
22	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
23	} from '../../../claudinite-tasks/shared-code/work-items.mjs';
24	import {
25	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
26	  outcomeOf as decodeOutcome,
27	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
28	  statusesOn, isParked, parkKindOf, triageLabelFor,
29	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL,
30	  NEEDS_HUMAN_FAILURE, isBlockingPark, parseLastVerdict,
31	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
32	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, hasLabel, labelNames,
33	} from '../../../claudinite-tasks/shared-code/work-items.mjs';
34	
35	export {
36	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
37	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
38	  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
39	};
40	
41	// How long a due item may sit blocked before the page calls the scheduler run out. The scheduler run
42	// is the repo's one cron, hourly; two fires of slack keeps a single late fire from
43	// reading as a fault. Not an engine constant because nothing engine-side measures
44	// this — the scheduler run readies due items on its next fire, whenever that is.
45	export const DUE_SLACK_MS = 2 * 3600e3;
46	
47	const ms = (t) => (t == null ? null : new Date(t).getTime());
48	
49	// --- where a declared pack's tasks live ---------------------------------------
50	
51	// A pack contributes tasks only if the repo DECLARES it: presence on disk is not
52	// activation (core's rule), and the mount carries packs a repo never declared. So
53	// the roster is built from the declaration list, and a task directory belonging to
54	// an undeclared pack is skipped rather than rendered greyed-out.
55	//
56	// Two roots, because the same code reads the canon home and a member: the home
57	// runs from the repo root (`packs/<id>`), a member from the mount
58	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
59	// from `../../.claudinite/local/packs/<name>` in both.
60	export function declaredPackDirs(config) {
61	  const dirs = new Map();
62	  for (const entry of config?.packs ?? []) {
63	    const id = typeof entry === 'string' ? entry : entry?.id;
64	    if (!id) continue;
65	    if (id.startsWith('local/')) {
66	      const name = id.slice('local/'.length);
67	      dirs.set(id, [`.claudinite/local/packs/${name}`]);
68	    } else {
69	      dirs.set(id, [`packs/${id}`, `.claudinite/shared/packs/${id}`]);
70	    }
71	  }
72	  return dirs;
73	}
74	
75	const TASK_PATH_RE = /^(.*)\/tasks\/([^/]+)\/task\.json$/;
76	
77	// Every declared pack's task declarations, from one recursive tree listing.
78	// `paths` is the flat list of blob paths the tree API returned.
79	export function taskDeclarationPaths(paths, config) {
80	  const dirs = declaredPackDirs(config);
81	  const found = [];
82	  for (const path of paths ?? []) {
83	    const m = TASK_PATH_RE.exec(path);
84	    if (!m) continue;
85	    const [, packDir, task] = m;
86	    for (const [pack, roots] of dirs) {
87	      if (roots.includes(packDir)) found.push({ pack, task, path });
88	    }
89	  }
90	  return found.sort((a, b) => `${a.pack}/${a.task}`.localeCompare(`${b.pack}/${b.task}`));
91	}
92	
93	// --- reading a task declaration -----------------------------------------------
94	
95	// The page reads a declaration as TEXT: it renders other repos over the API, where
96	// there is nothing to import and no Node to import it with. A `task.json` parses
97	// whole and takes the contract's defaults for the fields it omits — the same
98	// door the engine's loader runs it through.
99	//
100	// A field this cannot read comes back NULL and renders as "unknown". It is never
101	// defaulted: a task whose declaration this misreads must look unreadable, because a
102	// plausible wrong cadence would silently move a next-anchor the whole roster is
103	// read for. An ABSENT `preconditions` is not an unread one: a declaration that was
104	// read and carries no key requires nothing, exactly as its author wrote it, and
105	// reads as `[]`. An absent `trigger` is not unread either — it is derived, as the
106	// contract's own door derives it.
107	
108	// THE FREQUENCY DOOR, as the page runs it (#1725). `frequency` is retired: a task's
109	// cadence is a term in its own `preconditions`. A declaration still carrying the
110	// field — another repo's, read over the API — reads as the cadence term it always
111	// meant, first in the list, with the `none` it used to need beside it dropped; the
112	// field itself does not survive, and nothing downstream reads it. This is the
113	// contract's own rule (`normalizeTaskDeclaration` in `task-contract.mjs`), spelled
114	// again through the same `cadenceTermFor` because that module reaches into `node:`
115	// builtins the page cannot load; `model.test.mjs` runs both over one vector set so
116	// the two cannot drift apart unseen. `manual` meant no schedule and adds no term
117	// (`cadenceTermFor` answers null for it), so what stood beside it is the whole
118	// expression; nothing here writes the old word.
119	const NONE = 'none';
120	// THE TRIGGER DOOR, as the page runs it (#1725). `trigger` says whether the
121	// scheduler asks a task; a declaration written before the field is read off the
122	// shape of its conditions, exactly as the contract's door reads it. The one thing
123	// the page cannot do is resolve a task's OWN terms, so a legacy declaration whose
124	// condition reads the item itself is read here as scheduled — the engine's own door
125	// is handed those terms and is not; no canon declaration is in that state, and one
126	// stating its trigger never reaches this branch at all.
127	export const TRIGGER_SCHEDULE = 'schedule';
128	export const TRIGGER_REQUEST = 'request';
129	const withTrigger = (trigger, preconditions) => {
130	  if (trigger === TRIGGER_SCHEDULE || trigger === TRIGGER_REQUEST) return trigger;
131	  if (!Array.isArray(preconditions)) return null;
132	  return statesConditions(preconditions) ? TRIGGER_SCHEDULE : TRIGGER_REQUEST;
133	};
134	function withCadenceTerm(frequency, preconditions) {
135	  if (frequency == null) return preconditions;
136	  const term = cadenceTermFor(frequency);
137	  const stated = (preconditions ?? []).filter((c) => String(c).trim() !== NONE);
138	  return term === null || stated.some((c) => String(c).trim() === term) ? stated : [term, ...stated];
139	}
140	
141	// A task may decline to run; whether it CAN is the difference between "did not run"
142	// being routine and being a fault, so the roster shows it. The cadence terms say WHEN
143	// a task runs, not whether, and `none` is the EMPTY precondition — so neither is a

